@IsTest private class OwnedDateNullBoundary {
 public class Envelope { public Date value {get;} }
 private static Object decode(String body,Type target,Boolean strict) {
  try {
   Object value=strict?JSON.deserializeStrict(body,target):JSON.deserialize(body,target);
   return new Map<String,Object>{'returned'=>true,'isNull'=>value==null,'json'=>JSON.serialize(value)};
  } catch(Exception e) {return new Map<String,Object>{'type'=>e.getTypeName(),'message'=>e.getMessage()};}
 }
 private static Object valueOf(String text) {
  try {Date value=Date.valueOf(text);return new Map<String,Object>{'returned'=>true,'isNull'=>value==null,'json'=>JSON.serialize(value)};}
  catch(Exception e) {return new Map<String,Object>{'type'=>e.getTypeName(),'message'=>e.getMessage()};}
 }
 private static void finish(Object result) {
  System.assert(false,'OWNED_DATE_NULL_BOUNDARY|'+JSON.serialize(result));
 }
 @IsTest static void quotedDateNull() {
  finish(decode('"null"',Date.class,false));
 }
 @IsTest static void strictRootDateNull() {
  finish(new Map<String,Object>{'null'=>decode('null',Date.class,true),'quoted'=>decode('"null"',Date.class,true)});
 }
 @IsTest static void nestedDateNull() {
  finish(decode('{"value":null}',Envelope.class,false));
 }
 @IsTest static void dateCollectionNulls() {
  finish(new Map<String,Object>{'list'=>decode('[null]',List<Date>.class,false),'map'=>decode('{"owned":null}',Map<String,Date>.class,false)});
 }
 @IsTest static void otherScalarRootNulls() {
  finish(new Map<String,Object>{'integer'=>decode('null',Integer.class,false),'string'=>decode('null',String.class,false),'datetime'=>decode('null',Datetime.class,false)});
 }
 @IsTest static void valueOfControls() {
  finish(new Map<String,Object>{'null'=>valueOf(null),'quoted'=>valueOf('null'),'iso'=>valueOf('2004-02-29')});
 }
}

